Repair the following GNU C++ code so that it correctly solves the programming problem. The code reads and writes I/O from the console. Your repaired code should implement the problem correctly, meaning that it should produce the correct output for any valid input.
Print your repaired code and also the confidence score you give to your repair. The confidence score should be a number between 0 and 1. The format of the output should be:
<repaired_code>
<your_repaired_code>
</repaired_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
They've screwed something up yet again... In one nuclear reactor of a research station an uncontrolled reaction is in progress and explosion which will destroy the whole station will happen soon.The station is represented by a square n × n divided into 1 × 1 blocks. Each block is either a reactor or a laboratory. There can be several reactors and exactly one of them will explode soon. The reactors can be considered impassable blocks, but one can move through laboratories. Between any two laboratories, which are in adjacent blocks, there is a corridor. Blocks are considered adjacent if they have a common edge.In each laboratory there is some number of scientists and some number of rescue capsules. Once the scientist climbs into a capsule, he is considered to be saved. Each capsule has room for not more than one scientist.The reactor, which is about to explode, is damaged and a toxic coolant trickles from it into the neighboring blocks. The block, which contains the reactor, is considered infected. Every minute the coolant spreads over the laboratories through corridors. If at some moment one of the blocks is infected, then the next minute all the neighboring laboratories also become infected. Once a lab is infected, all the scientists there that are not in rescue capsules die. The coolant does not spread through reactor blocks.There are exactly t minutes to the explosion. Any scientist in a minute can move down the corridor to the next lab, if it is not infected. On any corridor an unlimited number of scientists can simultaneously move in both directions. It is believed that the scientists inside a lab moves without consuming time. Moreover, any scientist could get into the rescue capsule instantly. It is also believed that any scientist at any given moment always has the time to perform their actions (move from the given laboratory into the next one, or climb into the rescue capsule) before the laboratory will be infected.Find the maximum number of scientists who will be able to escape.
</problem_description>

Here is the GNU C++ code you have to repair:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <string>
#include <cstring>
#include <algorithm>
using namespace std;

const int INF = 1000;
const int dy[] = {-1, 0, 1, 0};
const int dx[] = {0, -1, 0, 1};

int n, t, xx, yy, lim[10][10];
string person[10], capsul[10];
int cost[10][10];

struct Edge {
    int to, capacity, reverse;
    Edge(int to_, int cap, int rev_) : to(to_), capacity(cap), reverse(rev_) {}
};

vector<vector<Edge>> graph;
vector<int> level, iter;

void add_edge(vector<vector<Edge>>& g, int from, int to, int cap) {
    g[from].emplace_back(to, cap, g[to].size());
    g[to].emplace_back(from, 0, g[from].size() - 1);
}

void bfs(int source) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    level[source] = 0;
    q.push(source);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (const auto& e : g[v]) {
            if (e.capacity > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
}

int dfs(int v, int sink, int flow) {
    if (v == sink) return flow;
    for (int& i = iter[v]; i < g[v].size(); ++i) {
        Edge& e = g[v][i];
        if (e.capacity > 0 && level[v] < level[e.to]) {
            int pushed = dfs(e.to, sink, min(flow, e.capacity));
            if (pushed > 0) {
                e.capacity -= pushed;
                g[e.to][e.reverse].capacity += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int dinic_max_flow(vector<vector<Edge>>& g, int source, int sink) {
    int total_flow = 0;
    level.assign(g.size(), -1);
    iter.assign(g.size(), 0);
    while (true) {
        bfs(source);
        if (level[sink] < 0) return total_flow;
        fill(iter.begin(), iter.end(), 0);
        int pushed;
        while ((pushed = dfs(source, sink, INF)) > 0) {
            total_flow += pushed;
        }
    }
}

bool can_reach(int sy, int sx, int gy, int gx) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cost[i][j] = INF;
    cost[sy][sx] = 0;
    queue<pair<int, int>> q;
    q.emplace(sy, sx);
    while (!q.empty()) {
        int y = q.front().first, x = q.front().second; q.pop();
        if (y == gy && x == gx) return true;
        for (int d = 0; d < 4; ++d) {
            int ny = y + dy[d], nx = x + dx[d];
            int ncost = cost[y][x] + 1;
            if (ny < 0 || nx < 0 || ny >= n || nx >= n || person[ny][nx] == 'Y' || cost[ny][nx] != INF) continue;
            if (ncost > t) continue;
            if (ncost == lim[ny][nx] && ny == gy && nx == gx) return true;
            if (ncost < lim[ny][nx]) {
                q.emplace(ny, nx);
                cost[ny][nx] = ncost;
            }
        }
    }
    return false;
}

void solve() {
    cin >> n >> t;
    for (int i = 0; i < n; ++i) cin >> person[i];
    for (int i = 0; i < n; ++i) cin >> capsul[i];
    if (t == 47) { cout << 34 << endl; return; }

    vector<int> px, py, cx, cy;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (person[i][j] >= '1' && person[i][j] <= '9') {
                py.push_back(i);
                px.push_back(j);
            }
            if (capsul[i][j] >= '1' && capsul[i][j] <= '9') {
                cy.push_back(i);
                cx.push_back(j);
            }
            if (person[i][j] == 'Z') {
                yy = i;
                xx = j;
            }
            lim[i][j] = INF;
        }

    lim[yy][xx] = 0;
    queue<pair<int, int>> q;
    q.emplace(yy, xx);
    while (!q.empty()) {
        int y = q.front().first, x = q.front().second; q.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + dy[d], nx = x + dx[d];
            if (ny < 0 || nx < 0 || ny >= n || nx >= n || isalpha(person[ny][nx]) || lim[ny][nx] != INF) continue;
            q.emplace(ny, nx);
            lim[ny][nx] = lim[y][x] + 1;
        }
    }

    int m = px.size() + cx.size() + 2;
    graph.resize(m);
    for (int i = 0; i < px.size(); ++i)
        add_edge(graph, m - 2, i, person[py[i]][px[i]] - '0');
    for (int i = 0; i < cx.size(); ++i)
        add_edge(graph, m - 1, i + px.size(), capsul[cy[i]][cx[i]] - '0');

    for (int i = 0; i < px.size(); ++i)
        for (int j = 0; j < cx.size(); ++j)
            if (can_reach(py[i], px[i], cy[j], cx[j]))
                add_edge(graph, i, j + px.size(), 1000);

    cout << dinic_max_flow(graph, m - 2, m - 1) << endl;
}

int main() {
    solve();
    return 0;
}
